-- 093: 科研平台、科研服务目录、服务申请跟踪和导入导出日志。
-- 只建立可配置业务对象，不写入演示平台、服务申请或虚构处理结果。
BEGIN;

CREATE TABLE IF NOT EXISTS "科研平台" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "平台名称" varchar(200) NOT NULL,
    "平台类型" varchar(80) NOT NULL DEFAULT '科研平台',
    "依托部门编号" integer REFERENCES "部门"("编号"),
    "负责人编号" integer REFERENCES "人员"("编号"),
    "平台简介" varchar(3000),
    "开放状态" varchar(20) NOT NULL DEFAULT '开放',
    "联系方式" varchar(300),
    "规章制度路径" varchar(1000),
    "年度报告年份" integer,
    "年度报告路径" varchar(1000),
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_科研平台_名称" UNIQUE ("平台名称"),
    CONSTRAINT "ck_科研平台_开放状态" CHECK ("开放状态" IN ('开放','预约','暂停','关闭')),
    CONSTRAINT "ck_科研平台_报告年份" CHECK ("年度报告年份" IS NULL OR "年度报告年份" BETWEEN 2000 AND 2200)
);
CREATE INDEX IF NOT EXISTS "ix_科研平台_状态" ON "科研平台" ("是否启用", "开放状态", "更新时间" DESC);

CREATE TABLE IF NOT EXISTS "科研平台成员" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "平台编号" bigint NOT NULL REFERENCES "科研平台"("编号") ON DELETE CASCADE,
    "人员编号" integer NOT NULL REFERENCES "人员"("编号"),
    "成员角色" varchar(50) NOT NULL DEFAULT '成员',
    "加入时间" date NOT NULL DEFAULT CURRENT_DATE,
    "退出时间" date,
    "备注" varchar(500),
    CONSTRAINT "uq_科研平台成员_平台人员" UNIQUE ("平台编号", "人员编号"),
    CONSTRAINT "ck_科研平台成员_日期" CHECK ("退出时间" IS NULL OR "退出时间" >= "加入时间")
);
CREATE INDEX IF NOT EXISTS "ix_科研平台成员_人员" ON "科研平台成员" ("人员编号", "退出时间");

CREATE TABLE IF NOT EXISTS "科研服务事项" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "服务编码" varchar(80) NOT NULL,
    "服务名称" varchar(200) NOT NULL,
    "服务分类" varchar(80) NOT NULL DEFAULT '科研公共服务',
    "服务说明" varchar(3000),
    "所需材料模板路径" varchar(1000),
    "办理角色" varchar(100),
    "办理时限天数" integer NOT NULL DEFAULT 5,
    "咨询电话" varchar(100),
    "是否启用" boolean NOT NULL DEFAULT TRUE,
    "创建人编号" integer REFERENCES "人员"("编号"),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_科研服务事项_编码" UNIQUE ("服务编码"),
    CONSTRAINT "ck_科研服务事项_时限" CHECK ("办理时限天数" BETWEEN 1 AND 365)
);
CREATE INDEX IF NOT EXISTS "ix_科研服务事项_分类状态" ON "科研服务事项" ("服务分类", "是否启用", "更新时间" DESC);

CREATE TABLE IF NOT EXISTS "科研服务申请" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "服务事项编号" bigint NOT NULL REFERENCES "科研服务事项"("编号"),
    "申请人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "关联业务类型" varchar(80),
    "关联业务编号" bigint,
    "申请说明" varchar(3000),
    "附件路径" varchar(2000),
    "状态" varchar(20) NOT NULL DEFAULT '待受理',
    "当前处理人编号" integer REFERENCES "人员"("编号"),
    "当前处理角色" varchar(100),
    "受理时间" timestamp without time zone,
    "完成时间" timestamp without time zone,
    "办理期限" timestamp without time zone,
    "处理意见" varchar(3000),
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "更新时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_科研服务申请_状态" CHECK ("状态" IN ('待受理','处理中','退回','已完成','已取消')),
    CONSTRAINT "ck_科研服务申请_完成时间" CHECK ("完成时间" IS NULL OR "受理时间" IS NULL OR "完成时间" >= "受理时间")
);
CREATE INDEX IF NOT EXISTS "ix_科研服务申请_申请人状态" ON "科研服务申请" ("申请人编号", "状态", "更新时间" DESC);
CREATE INDEX IF NOT EXISTS "ix_科研服务申请_待办" ON "科研服务申请" ("当前处理人编号", "当前处理角色", "状态", "办理期限");

CREATE TABLE IF NOT EXISTS "科研服务反馈" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "服务申请编号" bigint NOT NULL REFERENCES "科研服务申请"("编号") ON DELETE CASCADE,
    "评价人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "评价星级" integer NOT NULL,
    "反馈内容" varchar(2000),
    "是否公开" boolean NOT NULL DEFAULT FALSE,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "uq_科研服务反馈_申请评价人" UNIQUE ("服务申请编号", "评价人编号"),
    CONSTRAINT "ck_科研服务反馈_星级" CHECK ("评价星级" BETWEEN 1 AND 5)
);

CREATE TABLE IF NOT EXISTS "科研导入导出日志" (
    "编号" bigint GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "模块" varchar(100) NOT NULL,
    "操作类型" varchar(20) NOT NULL,
    "文件名称" varchar(500),
    "文件类型" varchar(100),
    "记录数" integer NOT NULL DEFAULT 0,
    "成功数" integer NOT NULL DEFAULT 0,
    "失败数" integer NOT NULL DEFAULT 0,
    "状态" varchar(20) NOT NULL DEFAULT '处理中',
    "操作人编号" integer NOT NULL REFERENCES "人员"("编号"),
    "是否可撤销" boolean NOT NULL DEFAULT FALSE,
    "撤销时间" timestamp without time zone,
    "详情" jsonb NOT NULL DEFAULT '{}'::jsonb,
    "创建时间" timestamp without time zone NOT NULL DEFAULT CURRENT_TIMESTAMP,
    CONSTRAINT "ck_科研导入导出日志_类型" CHECK ("操作类型" IN ('导入','导出')),
    CONSTRAINT "ck_科研导入导出日志_状态" CHECK ("状态" IN ('处理中','已完成','部分失败','失败','已撤销')),
    CONSTRAINT "ck_科研导入导出日志_数量" CHECK ("记录数" >= 0 AND "成功数" >= 0 AND "失败数" >= 0 AND "成功数" + "失败数" <= "记录数")
);
CREATE INDEX IF NOT EXISTS "ix_科研导入导出日志_模块时间" ON "科研导入导出日志" ("模块", "创建时间" DESC);

INSERT INTO "权限" ("编号", "上级编号", "名称", "路径", "类型", "备注")
VALUES (205, 2, '科研平台与服务目录', '科研办公/科研办公/科研平台与服务目录.html', TRUE, '维护科研平台、公共服务事项、服务申请和导入导出日志')
ON CONFLICT ("编号") DO UPDATE SET "名称"=EXCLUDED."名称", "路径"=EXCLUDED."路径", "备注"=EXCLUDED."备注";
INSERT INTO "角色权限" ("角色编号", "权限编号")
SELECT r."编号", 205 FROM "角色" r
WHERE r."名称" IN ('系统管理员','科研管理员','科技办')
  AND NOT EXISTS (SELECT 1 FROM "角色权限" rp WHERE rp."角色编号"=r."编号" AND rp."权限编号"=205);

UPDATE "系统迁移版本"
SET "版本"=93, "脚本"='093_research_platform_service_catalog.sql',
    "检查摘要"='增加科研平台、科研服务目录、服务申请跟踪和导入导出日志', "应用时间"=CURRENT_TIMESTAMP
WHERE "编号"=1;

COMMIT;
